function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 5 || nums.length > 1000) return 'nums needs 5 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1000000000 || v > 1000000000)) return 'Each value is a whole number from -10^9 to 10^9.';
  return null;
}

