function subsequencesWithMiddleMode(nums) {
  const MOD = 1000000007;
  const n = nums.length;
  const pairs = (k) => k * (k - 1) / 2;
  const ids = new Map();
  for (const value of nums) {
    if (!ids.has(value)) ids.set(value, ids.size);
  }
  const left = new Array(ids.size).fill(0);
  const right = new Array(ids.size).fill(0);
  for (const value of nums) {
    right[ids.get(value)]++;
  }
  let answer = 0;
  for (let middle = 0; middle < n; middle++) {
    const x = ids.get(nums[middle]);
    right[x]--;
    const leftOther = middle - left[x];
    const rightOther = n - 1 - middle - right[x];
    let good = pairs(middle) * pairs(n - 1 - middle) - pairs(leftOther) * pairs(rightOther);
    for (let v = 0; v < ids.size; v++) {
      if (v === x) continue;
      good -= left[x] * (leftOther * pairs(right[v]) + left[v] * right[v] * (rightOther - right[v]));
      good -= right[x] * (rightOther * pairs(left[v]) + right[v] * left[v] * (leftOther - left[v]));
    }
    answer = (answer + good) % MOD;
    left[x]++;
  }
  return answer;
}

