function subsequencesWithMiddleMode(nums) {
  // Try every choice of five positions and count each value's occurrences directly.
  const n = nums.length;
  let count = 0;
  for (let a = 0; a < n; a++)
    for (let b = a + 1; b < n; b++)
      for (let c = b + 1; c < n; c++)
        for (let d = c + 1; d < n; d++)
          for (let e = d + 1; e < n; e++) {
            const seq = [nums[a], nums[b], nums[c], nums[d], nums[e]];
            const times = (value) => seq.filter(v => v === value).length;
            const middle = times(seq[2]);
            if (seq.every(v => v === seq[2] || times(v) < middle)) count++;
          }
  return count % 1000000007;
}

