function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? int(900, 1000) : int(5, 12);
  // Draw from a pool of a few values so that repeats (and ties) are common.
  const kinds = size === 'large' ? [1, 2, 3, 5, 20, 100, 1000][int(0, 6)] : int(1, 5);
  const span = rand() < 0.3 ? 1000000000 : kinds;
  const pool = Array.from({ length: kinds }, () => int(-span, span));
  return [Array.from({ length: n }, () => pool[int(0, kinds - 1)])];
}
